mapper.select:
SELECT p.id, p.code, p.name, p.description, p.project_type as projectType, p.url, p.logo, p.icon, p.sort_no as sortNo, p.status, p.is_default as isDefault, p.target, p.create_time as createTime, p.update_time as updateTime, p.remark FROM sys_project p WHERE p.deleted = 0
AND p.name LIKE CONCAT('%', #{dto.name}, '%')
AND p.code = #{dto.code}
AND p.project_type = #{dto.projectType}
AND p.status = #{dto.status}
AND p.is_default = #{dto.isDefault}
ORDER BY p.sort_no ASC, p.create_time DESC
